def find_rect(g):
    color=None; rows=[]; cols=[]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v not in (0,):
                if color is None: color=v
                if v==color: rows.append(i); cols.append(j)
    return color,min(rows),max(rows),min(cols),max(cols)
def transform(g):
    H,W=len(g),len(g[0])
    color,r0,r1,c0,c1=find_rect(g)
    out=[row[:] for row in g]
    noise=set(v for row in g for v in row)-{0,color}
    for i in range(r0,r1+1):
        if not any(g[i][j] in noise for j in range(W)):
            out[i]=[color]*W
    for j in range(c0,c1+1):
        if not any(g[i][j] in noise for i in range(H)):
            for i in range(r1+1,H): out[i][j]=color
    return out
